public ATM(TransferUI ui) { this.transferUI = ui; }
public void deposit() {
int amount = depositUI.requestAmount();
// Process deposit
}
public void withdraw() {
int amount = withdrawalUI.requestAmount();
// Process withdrawal
}
public void transfer() {
