p.waitFor(); // Wait for the process to complete
logger.info("Process " + p + " is done.");
} catch (Exception ex) {
JOptionPane.showMessageDialog(this,
"Error" + ex, "Error", JOptionPane.ERROR_MESSAGE);
}
}
```
