public void onEvent(long timestamp) {
if (timestamp > currentMaxTimestamp) {
currentMaxTimestamp = timestamp;
}
}
public long getCurrentWatermark() {
return currentMaxTimestamp - ESTIMATION_BAND; // Adjust for the estimation band
}
}
