public double computeVariance(double p) {
// Compute E[X] and E[X^2]
double mean = 1 / p;
double secondMoment = (2 - p) / Math.pow(p, 2);
// Variance calculation
return secondMoment - Math.pow(mean, 2); // Placeholder for actual computation
}
}
```

