public MGA1Queue(double mu1, double mu2, double p) {
this.mu1 = mu1;
this.mu2 = mu2;
this.p = p;
}
public double expectedTimeInQueue(double lambda) {
return 1.0 / lambda + p * (1.0 / (mu1 - lambda)) + (1 - p) * (1.0 / (mu2 - lambda));
}
}
```

