int cap = 8; // seconds
for (int attempt = 1; ; attempt++) {
long delay = Math.min(cap, initialBackOff * Math.pow(2, attempt - 1));
try {
// Make the network call with timeout and backoff handling
break;
} catch (Exception e) {
// Log the exception or retry after exponential backoff
Thread.sleep(delay);
}
}
}
